#!/usr/bin/env bash
# Cria rótulos e issues (histórias de usuário) no repositório atual. Requer: gh auth login
set -e

for l in "prioridade:alta:d73a4a" "prioridade:media:fbca04" "prioridade:baixa:0e8a16" "papel:visitante:5319e7" "papel:leitor:1d76db" "papel:bibliotecario:0052cc" "papel:administrador:b60205"; do
  name="${l%:*}"; color="${l##*:}"
  gh label create "$name" --color "$color" --force >/dev/null
done

gh issue create --title 'US01: cadastrar livros e seus exemplares' --label 'prioridade:alta' --label 'papel:bibliotecario' --body 'Como bibliotecário, quero cadastrar livros e seus exemplares, para manter o acervo organizado e saber o que existe na biblioteca.' >/dev/null && echo 'US01 criado'
gh issue create --title 'US02: consultar o catálogo por título, autor ou categoria e ver quantos exem' --label 'prioridade:alta' --label 'papel:visitante' --body 'Como visitante, quero consultar o catálogo por título, autor ou categoria e ver quantos exemplares estão disponíveis, para saber se vale a pena ir à biblioteca.' >/dev/null && echo 'US02 criado'
gh issue create --title 'US03: entrar no sistema com login e senha' --label 'prioridade:alta' --label 'papel:leitor' --body 'Como usuário cadastrado, quero entrar no sistema com login e senha, para acessar apenas as funções do meu perfil.' >/dev/null && echo 'US03 criado'
gh issue create --title 'US04: me cadastrar como leitor' --label 'prioridade:alta' --label 'papel:visitante' --body 'Como visitante, quero me cadastrar como leitor, para poder reservar e pegar livros emprestados.' >/dev/null && echo 'US04 criado'
gh issue create --title 'US05: registrar o empréstimo de um exemplar a um leitor' --label 'prioridade:alta' --label 'papel:bibliotecario' --body 'Como bibliotecário, quero registrar o empréstimo de um exemplar a um leitor, para que a retirada fique registrada com a data de devolução prevista.' >/dev/null && echo 'US05 criado'
gh issue create --title 'US06: registrar a devolução de um exemplar' --label 'prioridade:alta' --label 'papel:bibliotecario' --body 'Como bibliotecário, quero registrar a devolução de um exemplar, para encerrar o empréstimo e liberar o exemplar.' >/dev/null && echo 'US06 criado'
gh issue create --title 'US07: que o sistema impeça empréstimo a leitor bloqueado, com multa pendente' --label 'prioridade:alta' --label 'papel:bibliotecario' --body 'Como bibliotecário, quero que o sistema impeça empréstimo a leitor bloqueado, com multa pendente ou acima do limite de empréstimos, para aplicar as regras da biblioteca sem conferência manual.' >/dev/null && echo 'US07 criado'
gh issue create --title 'US08: que a multa por atraso seja calculada automaticamente na devolução' --label 'prioridade:alta' --label 'papel:bibliotecario' --body 'Como bibliotecário, quero que a multa por atraso seja calculada automaticamente na devolução, para eliminar erros e esquecimentos.' >/dev/null && echo 'US08 criado'
gh issue create --title 'US09: reservar um livro sem exemplares disponíveis' --label 'prioridade:media' --label 'papel:leitor' --body 'Como leitor, quero reservar um livro sem exemplares disponíveis, para entrar na fila e ser atendido por ordem.' >/dev/null && echo 'US09 criado'
gh issue create --title 'US10: ver meus empréstimos, prazos, reservas e multas' --label 'prioridade:media' --label 'papel:leitor' --body 'Como leitor, quero ver meus empréstimos, prazos, reservas e multas, para não perder datas e não ser pego de surpresa.' >/dev/null && echo 'US10 criado'
gh issue create --title 'US11: renovar um empréstimo antes de vencer' --label 'prioridade:media' --label 'papel:leitor' --body 'Como leitor, quero renovar um empréstimo antes de vencer, para ficar mais tempo com o livro sem ir ao balcão.' >/dev/null && echo 'US11 criado'
gh issue create --title 'US12: registrar o pagamento de uma multa' --label 'prioridade:media' --label 'papel:bibliotecario' --body 'Como bibliotecário, quero registrar o pagamento de uma multa, para liberar o leitor a pegar novos livros.' >/dev/null && echo 'US12 criado'
gh issue create --title 'US13: cadastrar autores, editoras e categorias' --label 'prioridade:media' --label 'papel:bibliotecario' --body 'Como bibliotecário, quero cadastrar autores, editoras e categorias, para classificar corretamente os livros.' >/dev/null && echo 'US13 criado'
gh issue create --title 'US14: cadastrar, editar e bloquear leitores' --label 'prioridade:media' --label 'papel:bibliotecario' --body 'Como bibliotecário, quero cadastrar, editar e bloquear leitores, para manter a base de leitores correta.' >/dev/null && echo 'US14 criado'
gh issue create --title 'US15: cadastrar e desativar bibliotecários' --label 'prioridade:media' --label 'papel:administrador' --body 'Como administrador, quero cadastrar e desativar bibliotecários, para controlar quem opera o balcão.' >/dev/null && echo 'US15 criado'
gh issue create --title 'US16: configurar prazo de empréstimo, valor da multa e limite de empréstimos' --label 'prioridade:media' --label 'papel:administrador' --body 'Como administrador, quero configurar prazo de empréstimo, valor da multa e limite de empréstimos, para ajustar as regras sem alterar o sistema.' >/dev/null && echo 'US16 criado'
gh issue create --title 'US17: cancelar uma reserva' --label 'prioridade:media' --label 'papel:leitor' --body 'Como leitor, quero cancelar uma reserva, para liberar minha vez na fila quando não precisar mais do livro.' >/dev/null && echo 'US17 criado'
gh issue create --title 'US18: ser avisado quando o livro que reservei estiver disponível' --label 'prioridade:media' --label 'papel:leitor' --body 'Como leitor, quero ser avisado quando o livro que reservei estiver disponível, para retirá-lo dentro do prazo.' >/dev/null && echo 'US18 criado'
gh issue create --title 'US19: um relatório de empréstimos e atrasos por período' --label 'prioridade:baixa' --label 'papel:administrador' --body 'Como administrador, quero um relatório de empréstimos e atrasos por período, para acompanhar a inadimplência.' >/dev/null && echo 'US19 criado'
gh issue create --title 'US20: ver os livros mais emprestados' --label 'prioridade:baixa' --label 'papel:administrador' --body 'Como administrador, quero ver os livros mais emprestados, para decidir quais comprar ou repor.' >/dev/null && echo 'US20 criado'
